   117  static int
   118  zlibcmp(const unsigned char *buf)
   119  {
   120          unsigned short x = 1;
   121          unsigned char *s = CAST(unsigned char *, CAST(void *, &x));
   122
   123          if ((buf[0] & 0xf) != 8 || (buf[0] & 0x80) != 0)
   124                  return 0;
   125          if (s[0] != 1)  /* endianness test */
   126                  x = buf[0] | (buf[1] << 8);
   127          else
   128                  x = buf[1] | (buf[0] << 8);
   129          if (x % 31)
   130                  return 0;
   131          return 1;
   132  }
