   376  /*
   377   * `safe' write for sockets and pipes.
   378   */
   379  private ssize_t
   380  swrite(int fd, const void *buf, size_t n)
   381  {
   382          ssize_t rv;
   383          size_t rn = n;
   384
   385          do
   386                  switch (rv = write(fd, buf, n)) {
   387                  case -1:
   388                          if (errno == EINTR)
   389                                  continue;
   390                          return -1;
   391                  default:
   392                          n -= rv;
   393                          buf = CAST(const char *, buf) + rv;
   394                          break;
   395                  }
   396          while (n > 0);
   397          return rn;
   398  }
